import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import { AuthProvider } from './context/AuthContext';
import { ModalProvider } from './context/ModalContext';
import ProtectedRoute from './components/ProtectedRoute'; // Добавляем ProtectedRoute
import Navbar from './components/Navbar';
import Footer from './components/Footer';
import Home from './pages/Home';
import Catalog from './pages/Catalog';
import ProductPage from './pages/ProductPage';
import Profile from './pages/Profile';
import Auth from './pages/Auth';
import PrivacyPolicy from './pages/PrivacyPolicy';
import About from './pages/About';
import Contacts from './pages/Contacts';
import AuthPage from './components/AuthPage';
import ProductModal from './components/ProductModal';
import OrderSuccessModal from './components/OrderSuccessModal';
import Collections from './pages/Collections';
import CollectionDetail from './components/CollectionDetail';
import Cart from './pages/Cart'; // Добавляем страницу корзины
import NotFound from './pages/NotFound'; // Добавляем страницу 404

function App() {
  return (
    <ModalProvider>
      <AuthProvider>
        <Router>
          <div className="min-h-screen bg-white flex flex-col">
            <Navbar />
            <main className="flex-grow">
              <ProductModal />
              <OrderSuccessModal />
              <Routes>
                <Route path="/" element={<Home />} />
                <Route path="/catalog" element={<Catalog />} />
                <Route path="/collections" element={<Collections />} />
                <Route path="/collections/:id" element={<CollectionDetail />} />
                <Route path="/product/:id" element={<ProductPage />} />
                <Route path="/contacts" element={<Contacts />} />
                <Route path="/about" element={<About />} />
                <Route path="/privacy" element={<PrivacyPolicy />} />
                <Route path="/cart" element={<Cart />} /> {/* Добавляем корзину */}

                {/* Защищённые маршруты */}
                <Route 
                  path="/profile" 
                  element={
                    <ProtectedRoute>
                      <Profile />
                    </ProtectedRoute>
                  } 
                />

                {/* Маршруты аутентификации */}
                <Route 
                  path="/auth" 
                  element={
                    // Если пользователь уже авторизован, перенаправляем в профиль
                    <ProtectedRoute redirectTo="/profile">
                      <AuthPage />
                    </ProtectedRoute>
                  } 
                />

                <Route 
                  path="/login" 
                  element={
                    <ProtectedRoute redirectTo="/profile">
                      <Auth isLogin={true} />
                    </ProtectedRoute>
                  } 
                />

                <Route 
                  path="/register" 
                  element={
                    <ProtectedRoute redirectTo="/profile">
                      <Auth isLogin={false} />
                    </ProtectedRoute>
                  } 
                />

                {/* Страница 404 */}
                <Route path="/404" element={<NotFound />} />
                <Route path="*" element={<Navigate to="/404" replace />} />
              </Routes>
            </main>
            <Footer />
          </div>
        </Router>
      </AuthProvider>
    </ModalProvider>
  );
}

export default App;
